#include <stdio.h>
#include <sstream>
#include <iostream>
#include "wallet/monero_wallet_light_model.h"
#include "utils/monero_utils.h"
#include "utils/monero_wallet_utils.h"
#include "utils/gen_utils.h"
using namespace std;
using namespace monero;

// vectors captured from a regtest rig: a set that a view-only wallet built, and the same set
// with one destination amount raised by a single unit, re-encrypted with the view key - the
// shape of a holder of the view key rewriting a set between its describe and its sign
static const string UNSIGNED_HEX = "";
static const string MODIFIED_HEX = "";
static const string VIEW_KEY_HEX = "3d579a455e5bb4a49c06804b3b4f56e6a28e1ab7c85f563837eca28f4ef0a100";

void check(bool condition, const string& what) {
  if (!condition) { MERROR("FAIL: " << what); exit(1); }
  MINFO("ok: " << what);
}

boost::property_tree::ptree ptree_from(const string& json) {
  boost::property_tree::ptree node;
  std::istringstream iss(json);
  boost::property_tree::read_json(iss, node);
  return node;
}

void test_unspent_outs_validation() {
  // a full output parses
  auto response = std::make_shared<monero_get_unspent_outs_response>();
  monero_get_unspent_outs_response::from_property_tree(ptree_from(
    "{\"per_byte_fee\":\"2\",\"fee_mask\":\"1\",\"amount\":\"0\",\"outputs\":[{"
    "\"amount\":\"100\",\"public_key\":\"ab\",\"tx_pub_key\":\"cd\",\"index\":\"0\","
    "\"global_index\":\"5\",\"tx_hash\":\"ef\"}]}"), response);
  check(response->m_outputs.size() == 1, "a full unspent output parses");

  // an output that misses a field errors here, not as a crash of the sync deeper in
  bool threw = false;
  try {
    auto bad = std::make_shared<monero_get_unspent_outs_response>();
    monero_get_unspent_outs_response::from_property_tree(ptree_from(
      "{\"outputs\":[{\"amount\":\"100\",\"public_key\":\"ab\",\"index\":\"0\","
      "\"global_index\":\"5\",\"tx_hash\":\"ef\"}]}"), bad);
  } catch (const std::exception& e) {
    threw = string(e.what()).find("missing required output fields") != string::npos;
  }
  check(threw, "an unspent output that misses its tx pub key throws");
}

void test_address_txs_validation() {
  // a transaction the chain carries names its height
  auto response = std::make_shared<monero_get_address_txs_response>();
  monero_get_address_txs_response::from_property_tree(ptree_from(
    "{\"total_received\":\"100\",\"transactions\":[{\"hash\":\"ab\",\"mempool\":false,"
    "\"coinbase\":true,\"height\":\"5\",\"unlock_time\":\"0\",\"total_received\":\"100\","
    "\"total_sent\":\"0\"}]}"), response);
  check(response->m_transactions.size() == 1, "a confirmed tx with its height parses");

  // a transaction that only the mempool shows names no height, which is legal
  auto mempool = std::make_shared<monero_get_address_txs_response>();
  monero_get_address_txs_response::from_property_tree(ptree_from(
    "{\"total_received\":\"100\",\"transactions\":[{\"hash\":\"ab\",\"mempool\":true,"
    "\"coinbase\":false,\"unlock_time\":\"0\",\"total_received\":\"100\","
    "\"total_sent\":\"0\"}]}"), mempool);
  check(mempool->m_transactions.size() == 1, "a mempool tx without a height parses");

  // a confirmed transaction that names no height errors
  bool threw = false;
  try {
    auto bad = std::make_shared<monero_get_address_txs_response>();
    monero_get_address_txs_response::from_property_tree(ptree_from(
      "{\"total_received\":\"100\",\"transactions\":[{\"hash\":\"ab\",\"mempool\":false,"
      "\"coinbase\":true,\"unlock_time\":\"0\",\"total_received\":\"100\","
      "\"total_sent\":\"0\"}]}"), bad);
  } catch (const std::exception& e) {
    threw = string(e.what()).find("missing required transaction fields") != string::npos;
  }
  check(threw, "a confirmed tx without a height throws");
}

void test_commitment() {
  crypto::secret_key view_key;
  check(epee::string_tools::hex_to_pod(VIEW_KEY_HEX, view_key), "the view key parses");

  // the commitment of a set is stable, and a rewrite of the set changes it
  string first = monero_wallet_utils::get_unsigned_tx_commitment(UNSIGNED_HEX, view_key);
  string second = monero_wallet_utils::get_unsigned_tx_commitment(UNSIGNED_HEX, view_key);
  string rewritten = monero_wallet_utils::get_unsigned_tx_commitment(MODIFIED_HEX, view_key);
  check(first == second, "the commitment of the same set is stable");
  check(first != rewritten, "the commitment of a rewritten set differs");

  // a set that does not carry the magic errors
  bool threw = false;
  try { monero_wallet_utils::get_unsigned_tx_commitment("deadbeef", view_key); }
  catch (const std::exception& e) { threw = string(e.what()).find("Bad magic") != string::npos; }
  check(threw, "a set without the magic throws");
}

int main(int argc, const char* argv[]) {
  mlog_configure("log_light_model_tests.txt", true);
  mlog_set_log_level(1);
  test_unspent_outs_validation();
  test_address_txs_validation();
  test_commitment();
  MINFO("ALL PASSED");
  return 0;
}
